function Screen() {
    return (
        <>
            <div className="distortion">
                <CRTScreenEffect />
                <ZIndexProvider>
                    <MenuBar />
                    <HighlightProvider>
                        <Application
                            title="App 1"
                            initialPosition={{ x: 50, y: 50 }}
                            sections={[
                                { type: 'text', content: 'This is a portfolio description' },
                                { type: 'image', content: './project-image.png' },
                                { type: 'imageWithText', content: { image: './image.png', text: 'Image with a description' } },
                            ]}
                        />
                        <Application
                            title="App 2"
                            initialPosition={{ x: 150, y: 50 }}
                            sections={[
                                { type: 'text', content: 'This is another section for a different project' },
                                { type: 'video', content: './project-video.mp4' }
                            ]}
                        />
                    </HighlightProvider>
                </ZIndexProvider>
            </div>
        </>
    );
}

export default Screen;
